INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l53','put out (a fire)','',NULL,'/pʊt aʊt/','Firemen have put out the forest fire.','消防员扑灭了森林大火。','Please put out your cigarette.','请把烟熄掉。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l53','find out','',NULL,'/faɪnd aʊt/','They tried to find out how the fire began.','他们设法查出起火原因。','I''ll find out the truth.','我会查明真相。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l53','at last','',NULL,'/æt læst/','At last they put out the fire.','他们终于扑灭了火。','At last the train arrived.','火车终于到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l53','throw ... away','',NULL,'/θroʊ əˈweɪ/','People throw cigarette ends away.','人们扔掉烟头。','Don''t throw away the box.','别把盒子扔了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp1','choice','{"stem":"\"I ___ at this hotel five years ago.\"(一般过去时:5 年前的事)","options":["stay","have been staying","stayed","have stayed"],"answer_index":2,"stem_cn":"5 年前我在这家酒店住过。","explanation_cn":"有明确的过去时间 five years ago,用一般过去时。✓ I stayed at this hotel five years ago. ✗ have stayed / have been staying:现在完成(进行)不与 ago 连用;✗ stay:一般现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp1','choice','{"stem":"\"Yesterday the firemen ___ the ground carefully.\"(一般过去时:昨天检查)","options":["examine","examined","were examining","have examined"],"answer_index":1,"stem_cn":"昨天消防队员仔细检查了地面。","explanation_cn":"Yesterday 表明是过去某时的动作,用一般过去时;examine 的过去式是 examined。✓ Yesterday the firemen examined the ground. ✗ have examined:不与 yesterday 连用;✗ examine:一般现在;✗ were examining:此处是完成的动作不是进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp1','choice','{"stem":"\"A bird ___ up the snake from the ground.\"(一般过去时:snatch 的过去式)","options":["snatches","snatch","has snatched","snatched"],"answer_index":3,"stem_cn":"一只鸟把蛇从地上抓了起来。","explanation_cn":"叙述过去发生的动作用一般过去时;snatch 的过去式是 snatched。✓ A bird snatched up the snake. ✗ has snatched:此处是一连串过去动作,用一般过去;✗ snatches:一般现在;✗ snatch:原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp2','choice','{"stem":"\"At last firemen ___ out a big forest fire.\"(现在完成时:终于扑灭了)","options":["have put","put","have been putting","are putting"],"answer_index":0,"stem_cn":"消防队员终于扑灭了一场大火。","explanation_cn":"\"终于扑灭了、对现在有影响(火灭了)\"用现在完成时 have + 过去分词;put 的过去分词仍是 put。✓ At last firemen have put out a big forest fire. ✗ put:此处强调对现在的结果,用现在完成;✗ have been putting:强调持续,不合\"已扑灭\";✗ are putting:现在进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp2','choice','{"stem":"\"Have you ever ___ at this hotel?\"(现在完成时:stay 的过去分词)","options":["stay","staying","stayed","been staying"],"answer_index":2,"stem_cn":"你曾在这家酒店住过吗?","explanation_cn":"\"曾经…吗\"用现在完成时 Have you + 过去分词;stay 的过去分词是 stayed。✓ Have you ever stayed at this hotel? ✗ staying:现在分词;✗ stay:原形;✗ been staying:Have you been staying 强调持续,与 ever 不搭。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp2','choice','{"stem":"\"A fireman ___ just discovered the cause.\"(现在完成时:刚刚发现)","options":["have","is","was","has"],"answer_index":3,"stem_cn":"一名消防员刚刚发现了起火原因。","explanation_cn":"\"刚刚发现\"用现在完成时;主语 a fireman 单数用 has。✓ A fireman has just discovered the cause. ✗ have:主语单数不用 have;✗ is / was:不构成完成时。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp3','choice','{"stem":"\"Since then, they ___ to find out how the fire began.\"(现在完成进行时:一直试图)","options":["are trying","have been trying","tried","have tried"],"answer_index":1,"stem_cn":"从那时起,他们一直试图找出起火原因。","explanation_cn":"Since then 表\"从那时起一直\",强调持续用现在完成进行时 have been + 现在分词。✓ they have been trying to find out how the fire began. ✗ have tried:强调结果而非持续;✗ tried:一般过去;✗ are trying:现在进行不含\"从那时起\"。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp3','choice','{"stem":"\"I ___ at this hotel for three weeks.\"(现在完成进行时:一直住着)","options":["have been staying","stay","stayed","have stayed"],"answer_index":0,"stem_cn":"我一直住在这家酒店有 3 周了。","explanation_cn":"for three weeks 表一段时间一直,用现在完成进行时。✓ I have been staying at this hotel for three weeks. ✗ stayed:一般过去;✗ have stayed:不强调\"一直住着\";✗ stay:一般现在。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp3','choice','{"stem":"\"It ___ raining since yesterday.\"(现在完成进行时:一直在下)","options":["was","has been","has","is"],"answer_index":1,"stem_cn":"从昨天起一直在下雨。","explanation_cn":"since yesterday 表\"一直\",用现在完成进行时 has been + 现在分词。✓ It has been raining since yesterday. ✗ has:后面要加 been;✗ is:现在进行不含\"从昨天起一直\";✗ was:过去。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp4','choice','{"stem":"\"They ___ trying to find out the cause since then.\"(since then 一直:选现在完成进行时)","options":["had been","were","have been","are"],"answer_index":2,"stem_cn":"从那时起他们一直在设法找出原因。","explanation_cn":"since then 表\"从那时起一直\",选现在完成进行时 have been + 现在分词。✓ They have been trying since then. ✗ were:一般过去;✗ are:现在进行;✗ had been:过去完成进行,与 since then(到现在)不符。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp4','choice','{"stem":"\"I ___ this film three times; I know it well.\"(至今看过三次:选现在完成时)","options":["have been seeing","saw","see","have seen"],"answer_index":3,"stem_cn":"这部电影我看过三遍,很熟悉。","explanation_cn":"\"至今看过三次、对现在有影响(所以熟)\"用现在完成时。✓ I have seen this film three times. ✗ saw:一般过去,不强调对现在的影响;✗ have been seeing:完成进行不与具体次数连用;✗ see:一般现在。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp4','choice','{"stem":"\"He ___ to California last summer.\"(last summer 明确过去:选一般过去时)","options":["has been going","has gone","went","goes"],"answer_index":2,"stem_cn":"去年夏天他去了加利福尼亚。","explanation_cn":"last summer 是明确的过去时间,用一般过去时;go 的过去式是 went。✓ He went to California last summer. ✗ has gone / has been going:现在完成(进行)不与 last summer 连用;✗ goes:一般现在。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp5','choice','{"stem":"\"He threw the ball ___ me and I caught it.\"(把球''扔给''某人接,后接介词)","options":["at","for","away","to"],"answer_index":3,"stem_cn":"他把球扔给我,我接住了。","explanation_cn":"\"把某物扔给某人(让他接)\"用 throw sth to sb。✓ He threw the ball to me and I caught it. ✗ at:表朝目标砸(带攻击性);✗ away:扔掉;✗ for:搭配不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp5','choice','{"stem":"\"The boy threw a stone ___ the window and broke it.\"(朝目标''砸''东西,带攻击性)","options":["at","away","for","to"],"answer_index":0,"stem_cn":"男孩朝窗户扔了块石头,把玻璃打碎了。","explanation_cn":"\"朝某个目标砸东西(带攻击性)\"用 throw sth at。✓ The boy threw a stone at the window and broke it. ✗ to:表扔给某人接;✗ away:扔掉;✗ for:搭配不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp5','choice','{"stem":"\"People carelessly throw ___ cigarette ends.\"(把烟头''扔掉、丢弃'')","options":["off","at","away","to"],"answer_index":2,"stem_cn":"人们随手扔掉烟头。","explanation_cn":"\"扔掉、丢弃\"用 throw away。✓ People carelessly throw away cigarette ends. ✗ to:扔给某人;✗ at:朝目标砸;✗ off:搭配不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp6','choice','{"stem":"\"They were ___ sure that a cigarette end did not start the fire.\"(相当、十分,程度副词)","options":["quiet","quietly","quit","quite"],"answer_index":3,"stem_cn":"他们十分肯定不是烟头引起的火。","explanation_cn":"\"相当、十分\"用程度副词 quite。✓ They were quite sure. ✗ quiet:意思是\"安静的\",拼写和词义都不同;✗ quietly:安静地;✗ quit:放弃。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp6','choice','{"stem":"\"The class kept very ___ during the lesson.\"(安静的、寂静的)","options":["quiet","quietness","quite","quietly"],"answer_index":0,"stem_cn":"上课时全班很安静。","explanation_cn":"\"安静的、寂静的\"用 quiet。✓ The class kept very quiet. ✗ quite:意思是\"相当\";✗ quietly:副词\"安静地\";✗ quietness:名词。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',5,'am2_l53_gp6','choice','{"stem":"\"A bird had ___ the snake onto the wires.\"(把蛇''扔、抛''到电线上)","options":["fell","dropped","falling","fallen"],"answer_index":1,"stem_cn":"一只鸟把蛇扔到了电线上。","explanation_cn":"\"使某物落下、扔下\"用及物动词 drop,其过去分词是 dropped。✓ A bird had dropped the snake onto the wires. ✗ fallen / fell / falling:fall 是\"(自己)落下\",后面不能接宾语 the snake。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"美语里\"手电筒\"常说:","options":["flashlight","hand lamp","torch","pocket light"],"answer_index":0,"explanation_cn":"美语\"手电筒\"常说 flashlight;英式说 torch。✓ shine a flashlight 用手电照。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"美语里\"消防员\"常说:","options":["fireman","fire guard","firefighter","fire officer"],"answer_index":2,"explanation_cn":"美语现代\"消防员\"常说 firefighter(中性);英式旧称 fireman。✓ The firefighters put out the fire."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"cause 的意思是:","options":["原因;引起","谜","结果","解决"],"answer_index":0,"explanation_cn":"cause = 原因;(动词)引起。✓ discovered the cause 发现了原因。\n顺带记:结果 = result;解决 = solve;谜 = mystery."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"solve 的意思是:","options":["隐藏","解决,解答","燃烧","制造"],"answer_index":1,"explanation_cn":"solve = 解决、解答。✓ solve the mystery 解开谜团。\n顺带记:制造 = make;隐藏 = hide;燃烧 = burn."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"mystery 的意思是:","options":["历史","故事","事实","谜,神秘的事"],"answer_index":3,"explanation_cn":"mystery = 谜、神秘的事。✓ solve the mystery 解开谜。\n顺带记:历史 = history;故事 = story;事实 = fact."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',6,NULL,'choice','{"stem":"examine 的意思是:","options":["扔掉","检查,仔细查看","抓住","缠绕"],"answer_index":1,"explanation_cn":"examine = 检查、仔细查看。✓ examined the ground carefully 仔细查看地面。\n顺带记:扔掉 = throw away;缠绕 = wind;抓住 = snatch."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',7,NULL,'cloze','{"stem":"第 1 空","context":"At last firemen ___1___ out a big forest fire. Since then, they ___2___ to find out how the fire began. Yesterday the firemen ___3___ the ground carefully, but ___4___ not able to find any glass.","blank_no":1,"options":["have put","have been putting","putting","are put"],"answer_index":0,"explanation_cn":"\"终于扑灭了、对现在有影响\"用现在完成时;put 的过去分词仍是 put。✓ At last firemen have put out a big forest fire.\n✗ have been putting:强调持续,与\"已扑灭\"矛盾;✗ putting / are put:形式不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',7,NULL,'cloze','{"stem":"第 2 空","context":"At last firemen ___1___ out a big forest fire. Since then, they ___2___ to find out how the fire began. Yesterday the firemen ___3___ the ground carefully, but ___4___ not able to find any glass.","blank_no":2,"options":["have been trying","trying","are trying","tried"],"answer_index":0,"explanation_cn":"Since then 表\"从那时起一直\",用现在完成进行时。✓ they have been trying to find out how the fire began.\n✗ trying / are trying:与\"从那时起一直\"不符;✗ tried:一般过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',7,NULL,'cloze','{"stem":"第 3 空","context":"At last firemen ___1___ out a big forest fire. Since then, they ___2___ to find out how the fire began. Yesterday the firemen ___3___ the ground carefully, but ___4___ not able to find any glass.","blank_no":3,"options":["examined","have examined","examine","examining"],"answer_index":0,"explanation_cn":"Yesterday 表过去某时,用一般过去时;examine 的过去式是 examined。✓ Yesterday the firemen examined the ground.\n✗ have examined:不与 yesterday 连用;✗ examine:一般现在;✗ examining:缺助动词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',7,NULL,'cloze','{"stem":"第 4 空","context":"At last firemen ___1___ out a big forest fire. Since then, they ___2___ to find out how the fire began. Yesterday the firemen ___3___ the ground carefully, but ___4___ not able to find any glass.","blank_no":4,"options":["were","have been","are","was"],"answer_index":0,"explanation_cn":"与前面 examined 并列的过去动作,主语 firemen 复数用 were。✓ but were not able to find any glass.\n✗ have been:时态不一致;✗ are:现在;✗ was:主语复数不用 was。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',8,NULL,'choice','{"stem":"What did the firemen put out?","options":["A house fire","A big forest fire in California","A car fire","A factory fire"],"answer_index":1,"explanation_cn":"课文说 firemen have put out a big forest fire in California。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',8,NULL,'choice','{"stem":"What was the real cause of the fire?","options":["A snake wound round the electric wires sent sparks to the ground","Broken glass","A cigarette end","Lightning"],"answer_index":0,"explanation_cn":"课文说蛇缠在电线上,it sent sparks down to the ground and these immediately started a fire。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',8,NULL,'choice','{"stem":"How did the snake get onto the wires?","options":["It fell from a tree","It climbed a pole","Someone threw it","A bird snatched it up and dropped it there"],"answer_index":3,"explanation_cn":"课文说 A bird had snatched up the snake from the ground and then dropped it on to the wires。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',9,NULL,'choice','{"stem":"你想说\"5 年前我在这家酒店住过\"(明确过去时间 five years ago,用一般过去时):","options":["I have been staying at this hotel five years ago.","I stay at this hotel five years ago.","I have stayed at this hotel five years ago.","I stayed at this hotel five years ago."],"answer_index":3,"explanation_cn":"有明确过去时间 five years ago,用一般过去时(不用现在完成)。✓ I stayed at this hotel five years ago. 场合:说过去某个确定时间做过的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',9,NULL,'choice','{"stem":"你想说\"从那时起他们一直在设法找出原因\"(since then 强调持续,用现在完成进行时):","options":["Since then, they have been trying to find out the cause.","Since then, they are trying to find out the cause.","Since then, they will try to find out the cause.","Since then, they tried to find out the cause."],"answer_index":0,"explanation_cn":"since then 表\"从那时起一直\",强调持续用现在完成进行时。✓ Since then, they have been trying to find out the cause. 场合:说从过去某时到现在一直在做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',9,NULL,'choice','{"stem":"你想说\"男孩朝窗户扔石头,把玻璃打碎了\"(朝目标砸用 throw ... at):","options":["The boy threw a stone to the window and broke it.","The boy threw a stone at the window and broke it.","The boy threw a stone away the window and broke it.","The boy threw a stone for the window and broke it."],"answer_index":1,"explanation_cn":"\"朝某个目标砸东西\"用 throw sth at;throw sth to 是\"扔给某人接\"。✓ The boy threw a stone at the window and broke it. 场合:说朝某物砸东西。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"cause 的意思是:","options":["原因;引起","谜","解决","结果"],"answer_index":0,"explanation_cn":"cause = 原因;(动词)引起。✓ discovered the cause 发现原因。\n顺带记:结果 = result;解决 = solve;谜 = mystery."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"mystery 的意思是:","options":["故事","事实","历史","谜,神秘的事"],"answer_index":3,"explanation_cn":"mystery = 谜、神秘的事。✓ solve the mystery 解开谜。\n顺带记:历史 = history;故事 = story;事实 = fact."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"\"At last firemen ___ out a big forest fire.\"(现在完成时)","options":["put","have put","have been putting","are putting"],"answer_index":1,"stem_cn":"消防队员终于扑灭了一场大火。","explanation_cn":"\"终于扑灭了、对现在有影响\"用现在完成时;put 的过去分词仍是 put。✓ At last firemen have put out a big forest fire.\n✗ put:此处强调对现在的结果;✗ are putting:现在进行;✗ have been putting:强调持续,与\"已扑灭\"矛盾。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"\"Since then, they ___ to find out how it began.\"(现在完成进行时)","options":["have tried","tried","are trying","have been trying"],"answer_index":3,"stem_cn":"从那时起,他们一直设法查出起火原因。","explanation_cn":"Since then 表\"从那时起一直\",用现在完成进行时。✓ Since then, they have been trying to find out how it began.\n✗ have tried:强调结果;✗ tried:一般过去;✗ are trying:现在进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"\"at last\" 这个短语的意思是:","options":["立刻","从不","最后,终于","起初"],"answer_index":2,"explanation_cn":"at last = 最后、终于(经过一段时间之后)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"\"put out the fire\" 这个短语的意思是:","options":["生火做饭","看着火","点燃火","扑灭火"],"answer_index":3,"explanation_cn":"put out the fire = 扑灭火(put out 熄灭、扑灭)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"What really caused the fire?","options":["Broken glass focused the sun","A lightning strike","A snake wound round the wires sent sparks to the ground","A carelessly thrown cigarette end"],"answer_index":2,"passage":"At last firemen have put out a big forest fire in California. Since then, they have been trying to find out how the fire began. Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away. Yesterday the firemen examined the ground carefully, but were not able to find any broken glass. They were also quite sure that a cigarette end did not start the fire. This morning, however, a fireman accidentally discovered the cause. He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line. In this way, he was able to solve the mystery. The explanation was simple but very unusual. A bird had snatched up the snake from the ground and then dropped it on to the wires. The snake then wound itself round the wires. When it did so, it sent sparks down to the ground and these immediately started a fire.","explanation_cn":"课文说死蛇缠在电线上,通电后 it sent sparks down to the ground,火花引起大火。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"Why couldn''t the firemen blame broken glass or a cigarette end?","options":["They didn''t look carefully","Someone removed the evidence","It had all burned away","Neither had caused it — the real cause was the snake"],"answer_index":3,"passage":"At last firemen have put out a big forest fire in California. Since then, they have been trying to find out how the fire began. Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away. Yesterday the firemen examined the ground carefully, but were not able to find any broken glass. They were also quite sure that a cigarette end did not start the fire. This morning, however, a fireman accidentally discovered the cause. He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line. In this way, he was able to solve the mystery. The explanation was simple but very unusual. A bird had snatched up the snake from the ground and then dropped it on to the wires. The snake then wound itself round the wires. When it did so, it sent sparks down to the ground and these immediately started a fire.","explanation_cn":"课文说未发现碎玻璃、也肯定不是烟头,真正的起因是那条缠在电线上的蛇。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"How did the snake get onto the high wires?","options":["A worker put it there","It slithered up the pole","A bird snatched it up and dropped it there","It was blown by the wind"],"answer_index":2,"audio":"At last firemen have put out a big forest fire in California. Since then, they have been trying to find out how the fire began. Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away. Yesterday the firemen examined the ground carefully, but were not able to find any broken glass. They were also quite sure that a cigarette end did not start the fire. This morning, however, a fireman accidentally discovered the cause. He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line. In this way, he was able to solve the mystery. The explanation was simple but very unusual. A bird had snatched up the snake from the ground and then dropped it on to the wires. The snake then wound itself round the wires. When it did so, it sent sparks down to the ground and these immediately started a fire.","explanation_cn":"课文说 A bird had snatched up the snake from the ground and then dropped it on to the wires。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l53',10,NULL,'choice','{"stem":"What happened when the snake wound round the wires?","options":["The power quietly went out","It flew away","Nothing happened","It sent sparks to the ground and started a fire"],"answer_index":3,"audio":"At last firemen have put out a big forest fire in California. Since then, they have been trying to find out how the fire began. Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away. Yesterday the firemen examined the ground carefully, but were not able to find any broken glass. They were also quite sure that a cigarette end did not start the fire. This morning, however, a fireman accidentally discovered the cause. He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line. In this way, he was able to solve the mystery. The explanation was simple but very unusual. A bird had snatched up the snake from the ground and then dropped it on to the wires. The snake then wound itself round the wires. When it did so, it sent sparks down to the ground and these immediately started a fire.","explanation_cn":"课文说 it sent sparks down to the ground and these immediately started a fire。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l54',2,7,54,'Sticky fingers','粘糊的手指','KS30 冠词 a/an/the 与 some/any 综合复习(some 肯定/any 疑问否定、a/an 泛指、the 特指、the+形容词表群体、the+最高级 vs most、零冠词固定短语)(教材 L54 Key structures)主考;课文 no sooner…than、What a mess、ring back、pick up、sign for(辅考)','早饭后,我送孩子们上学,然后就去了商店。我回到家时,时间还早。孩子们在上学,我丈夫在上班,家里清静得很。于是我决定做些肉馅饼。不一会儿我就忙着调拌起了黄油和面粉,很快我的手上就沾满了粘粘的面糊。恰恰在此时,电话铃响了。没有什么能比这更烦人了。我用两个沾满面糊的手指捏起了话筒。当我听出是海伦·贝茨的声音时,非常丧气。我用了 10 分钟的时间才说服她过会儿再来电话。我终于挂上了话筒。真是糟糕透了!我的手指上、电话机上以及门的把手上,都沾上了面糊。我刚回到厨房,门铃又响了起来,响声足以把死人唤醒。这次是邮递员,他要我签收一封挂号信!','{"q":"Listen and answer — What two interruptions did the writer have?","options":["The telephone rang, then the doorbell rang","A visitor and a fire","Two phone calls from Helen","Her children came home twice"],"answer_index":0}'::jsonb,'{"title":"冠词 a/an/the 与 some/any","intro":"KS30 综合复习冠词和 some/any:some 多用于肯定句,any 多用于疑问句和否定句;a/an 泛指''一个'',the 特指;the + 形容词可表''一类人''(the rich 富人、the poor 穷人);最高级前用 the,但''大多数''用 most(不加 the)。","table":{"headers":["用法","例子"],"rows":[["some(肯定)/ any(疑问·否定)","I want some. / Did you get any?"],["a/an 泛指一个","We need a new cinema."],["the 特指","The school in our village…"],["the + 形容词=一类人","The rich should help the poor."],["the + 最高级 / most 大多数","the most interesting / Most people"]]},"specialRules":[{"rule":"go to school / at work / go to bed 等固定短语用零冠词(表抽象概念);go to the cinema / the theater 用 the。","mark":"零冠词 vs the"},{"rule":"no sooner … than 表''刚…就…'';enough 作副词修饰形容词/副词时放在其后(loud enough)。","mark":"课文短语"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',1,NULL,'After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home.','早饭后,我送孩子们上学,然后就去了商店。我回到家时,时间还早。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',2,NULL,'The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies.','孩子们在上学,我丈夫在上班,家里清静得很。于是我决定做些肉馅饼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',3,NULL,'In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry.','不一会儿我就忙着调拌起了黄油和面粉,很快我的手上就沾满了粘粘的面糊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',4,NULL,'At exactly that moment, the telephone rang. Nothing could have been more annoying.','恰恰在此时,电话铃响了。没有什么能比这更烦人了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',5,NULL,'I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates.','我用两个沾满面糊的手指捏起了话筒。当我听出是海伦·贝茨的声音时,非常丧气。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',6,NULL,'It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess!','我用了 10 分钟才说服她过会儿再来电话。我终于挂上了话筒。真是糟糕透了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',7,NULL,'There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead.','我的手指上、电话机上以及门把手上都沾上了面糊。我刚回到厨房,门铃又响了起来,响声足以把死人唤醒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l54',8,NULL,'This time it was the postman and he wanted me to sign for a registered letter!','这次是邮递员,他要我签收一封挂号信!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
