INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l54','no sooner ... than','',NULL,'/noʊ ˈsuːnər ðæn/','I had no sooner got back than the doorbell rang.','我刚回来门铃就响了。','No sooner had he left than it rained.','他刚走就下雨了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l54','What a mess!','',NULL,'/wʌt ə mes/','Pastry everywhere — what a mess!','到处是面糊,真是一团糟!','Look at this room. What a mess!','看看这屋子,乱死了!') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l54','pick up (the receiver)','',NULL,'/pɪk ʌp/','I picked up the receiver.','我拿起了话筒。','Pick up the phone, please.','请接一下电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l54','sign for','',NULL,'/saɪn fɔːr/','He wanted me to sign for a registered letter.','他要我签收一封挂号信。','Please sign for the parcel.','请签收这个包裹。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp1','choice','{"stem":"\"I want ___ information about the trip.\"(肯定句里表''一些'')","options":["the","a","some","any"],"answer_index":2,"stem_cn":"我想要一些有关旅行的信息。","explanation_cn":"肯定句中表示\"一些\"用 some。✓ I want some information. ✗ any:多用于疑问句、否定句;✗ a:information 是不可数名词,不加 a;✗ the:此处不是特指。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp1','choice','{"stem":"\"Did you get ___ information?\"(疑问句里表''任何、什么'')","options":["any","the","some","a"],"answer_index":0,"stem_cn":"你得到什么消息了吗?","explanation_cn":"疑问句中表示\"任何、什么\"用 any。✓ Did you get any information? ✗ some:多用于肯定句;✗ a:information 不可数;✗ the:此处不是特指。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp1','choice','{"stem":"\"There isn''t ___ news in the paper today.\"(否定句里表''任何'')","options":["some","a","the","any"],"answer_index":3,"stem_cn":"今天报上没什么消息。","explanation_cn":"否定句中表示\"任何\"用 any。✓ There isn''t any news in the paper today. ✗ some:多用于肯定句;✗ a:news 不可数;✗ the:此处不是特指。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp1','choice','{"stem":"\"I did ___ work before breakfast.\"(肯定句里表''一些'')","options":["any","the","some","a"],"answer_index":2,"stem_cn":"我早饭前干了点活。","explanation_cn":"肯定句中表示\"一些\"用 some。✓ I did some work before breakfast. ✗ any:多用于疑问、否定句;✗ a:work 不可数;✗ the:此处不是特指。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp2','choice','{"stem":"\"We need ___ new cinema in our town.\"(泛指一座,用不定冠词)","options":["some","a","an","the"],"answer_index":1,"stem_cn":"我们镇需要一座新电影院。","explanation_cn":"泛指\"一座(新电影院)\",用不定冠词;cinema 以辅音音素开头,用 a。✓ We need a new cinema. ✗ an:用于元音音素开头的词前;✗ the:此处非特指;✗ some:后接单数可数名词一般用 a。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp2','choice','{"stem":"\"He is ___ honest man.\"(honest 的 h 不发音,首音是元音)","options":["an","the","one","a"],"answer_index":0,"stem_cn":"他是个诚实的人。","explanation_cn":"honest 的 h 不发音,首音是元音,前面用 an。✓ He is an honest man. ✗ a:用于辅音音素开头的词前;✗ the:此处泛指;✗ one:强调\"一个\"数量,此处只需冠词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp2','choice','{"stem":"\"In ___ short time I was busy mixing butter and flour.\"(泛指一段短时间的不定冠词)","options":["the","a","an","some"],"answer_index":1,"stem_cn":"不一会儿我就忙着拌黄油和面粉。","explanation_cn":"泛指\"一段短时间\"用不定冠词 a(In a short time = 不久)。✓ In a short time I was busy mixing. ✗ an:short 以辅音开头;✗ the:此处非特指;✗ some:short time 用 a。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp3','choice','{"stem":"\"___ school in our village was built last year.\"(特指本村那所学校的定冠词)","options":["A","An","The","Some"],"answer_index":2,"stem_cn":"我们村的那所学校是去年建的。","explanation_cn":"特指\"我们村的那所学校\",用定冠词。✓ The school in our village was built last year. ✗ A/An:此处是特指不是泛指;✗ Some:后接单数不用 some。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp3','choice','{"stem":"\"The rich should help ___ poor.\"(在形容词 poor 前加冠词表''穷人''这一类人)","options":["any","the","some","a"],"answer_index":1,"stem_cn":"富人应该帮助穷人。","explanation_cn":"\"the + 形容词\"表示一类人;the poor = 穷人。✓ The rich should help the poor. ✗ a:the poor 表一类人不用 a;✗ some/any:此处用 the 表整类。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp3','choice','{"stem":"\"There are organizations to help the deaf and ___ blind.\"(在形容词 blind 前加冠词表''盲人''这一类人)","options":["the","any","some","a"],"answer_index":0,"stem_cn":"有些组织帮助聋人和盲人。","explanation_cn":"\"the + 形容词\"表示一类人;the blind = 盲人。✓ organizations to help the deaf and the blind. ✗ a:表一类人用 the;✗ some/any:此处用 the 表整类。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp4','choice','{"stem":"\"The children went to ___ early this morning.\"(上学·表抽象概念,用零冠词)","options":["the school","school","a school","some school"],"answer_index":1,"stem_cn":"孩子们一早就上学了。","explanation_cn":"go to school 表示\"上学\"这一抽象概念,用零冠词。✓ The children went to school early this morning. ✗ the school:指具体某所学校(如去参观),此处是\"上学\";✗ a school / some school:与\"上学\"含义不符。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp4','choice','{"stem":"\"I often go to ___ at weekends.\"(去看电影这个习惯说法,cinema 前加定冠词)","options":["some cinema","a cinema","cinema","the cinema"],"answer_index":3,"stem_cn":"周末我常去看电影。","explanation_cn":"go to the cinema 表示\"去看电影\"这一习惯说法,用 the。✓ I often go to the cinema at weekends. ✗ a cinema:不表\"去看电影\"的习惯;✗ cinema:此处需加 the;✗ some cinema:含义不符。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp4','choice','{"stem":"\"My husband was at ___.\"(在上班·固定短语,用零冠词)","options":["a work","some work","work","the work"],"answer_index":2,"stem_cn":"我丈夫在上班。","explanation_cn":"at work 表示\"在上班\",是固定短语,用零冠词。✓ My husband was at work. ✗ the work / a work / some work:at work 固定不加冠词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp5','choice','{"stem":"\"It is ___ most interesting exhibition I have ever seen.\"(最高级 most interesting 前加的定冠词)","options":["the","a","an","some"],"answer_index":0,"stem_cn":"这是我看过的最有趣的展览。","explanation_cn":"最高级前用定冠词 the。✓ It is the most interesting exhibition I have ever seen. ✗ a/an:最高级前不用不定冠词;✗ some:含义不符。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp5','choice','{"stem":"\"___ people enjoyed the film.\"(表''大多数人'',直接用这个词、不加冠词)","options":["Some most","A most","The most","Most"],"answer_index":3,"stem_cn":"大多数人喜欢这部电影。","explanation_cn":"表示\"大多数(人)\"用 most,前面不加冠词。✓ Most people enjoyed the film. ✗ The most:the most 用于最高级(the most interesting),不表\"大多数\";✗ A most / Some most:搭配不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp6','choice','{"stem":"\"I had no sooner got back to the kitchen ___ the doorbell rang.\"(表''刚一…就…''的固定结构后半)","options":["than","when","then","that"],"answer_index":0,"stem_cn":"我刚回到厨房,门铃就响了。","explanation_cn":"no sooner … than 表示\"刚一…就…\",与 no sooner 搭配的是 than。✓ I had no sooner got back to the kitchen than the doorbell rang. ✗ then:是\"然后\";✗ that / when:不与 no sooner 构成这个固定结构。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp6','choice','{"stem":"\"What a ___! There was pastry everywhere.\"(表''真是一团糟、真狼狈'')","options":["messy","mess","miss","mass"],"answer_index":1,"stem_cn":"真是一团糟!到处都是面糊。","explanation_cn":"\"真是一团糟、真狼狈\"用 What a mess!✓ What a mess! There was pastry everywhere. ✗ messy:是形容词,不用于 What a ___ 结构;✗ mass:是\"大量、质量\";✗ miss:是\"错过、想念\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',5,'am2_l54_gp6','choice','{"stem":"\"It took ten minutes to persuade her to ring ___ later.\"(晚点再回电话)","options":["again to","up back","for","back"],"answer_index":3,"stem_cn":"花了十分钟才说服她晚点再打来。","explanation_cn":"\"晚点再回电话\"用 ring back(later)。✓ persuade her to ring back later. ✗ again to:语序和搭配都不对;✗ up back:没有这个搭配;✗ for:含义不符。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"美语里\"邮递员\"常说:","options":["mailman","postal man","post carrier","postman"],"answer_index":0,"explanation_cn":"美语\"邮递员\"常说 mailman(或 mail carrier);英式说 postman。✓ The mailman brought a letter."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"美语里\"水龙头\"常说:","options":["water valve","tap","spout","faucet"],"answer_index":3,"explanation_cn":"美语\"水龙头\"常说 faucet;英式说 tap。✓ Turn off the faucet."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"annoying 的意思是:","options":["恼人的,讨厌的","方便的","安静的","有趣的"],"answer_index":0,"explanation_cn":"annoying = 恼人的、讨厌的。✓ Nothing could have been more annoying 没什么比这更烦人。\n顺带记:有趣的 = interesting;安静的 = quiet;方便的 = convenient."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"persuade 的意思是:","options":["忘记","命令","拒绝","说服,劝说"],"answer_index":3,"explanation_cn":"persuade = 说服、劝说。✓ persuade her to ring back 说服她再打来。\n顺带记:命令 = order;拒绝 = refuse;忘记 = forget."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"recognize 的意思是:","options":["怀疑","认出,听出","介绍","忘记"],"answer_index":1,"explanation_cn":"recognize = 认出、听出。✓ recognized the voice 听出了声音。\n顺带记:忘记 = forget;怀疑 = doubt;介绍 = introduce."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',6,NULL,'choice','{"stem":"mess 的意思是:","options":["乱七八糟,狼狈","餐食","消息","整洁"],"answer_index":0,"explanation_cn":"mess = 乱七八糟、一团糟、狼狈。✓ What a mess! 真是一团糟!\n顺带记:整洁 = tidy;餐食 = meal;消息 = news."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',7,NULL,'cloze','{"stem":"第 1 空","context":"After breakfast, I sent ___1___ children to school. Then I decided to make ___2___ meat pies. In ___3___ short time my hands were covered with sticky pastry. At exactly that moment, ___4___ telephone rang.","blank_no":1,"options":["the","a","some","an"],"answer_index":0,"explanation_cn":"特指\"我(自己)的孩子们\",用定冠词 the。✓ I sent the children to school.\n✗ a / an:后接复数不用 a/an;✗ some:此处特指自己的孩子。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',7,NULL,'cloze','{"stem":"第 2 空","context":"After breakfast, I sent ___1___ children to school. Then I decided to make ___2___ meat pies. In ___3___ short time my hands were covered with sticky pastry. At exactly that moment, ___4___ telephone rang.","blank_no":2,"options":["some","a","the","any"],"answer_index":0,"explanation_cn":"肯定句中表示\"一些(肉馅饼)\"用 some。✓ I decided to make some meat pies.\n✗ a:后接复数 pies 不用 a;✗ the:此处非特指;✗ any:多用于疑问、否定句。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',7,NULL,'cloze','{"stem":"第 3 空","context":"After breakfast, I sent ___1___ children to school. Then I decided to make ___2___ meat pies. In ___3___ short time my hands were covered with sticky pastry. At exactly that moment, ___4___ telephone rang.","blank_no":3,"options":["a","the","an","some"],"answer_index":0,"explanation_cn":"泛指\"一段短时间\"用不定冠词 a(In a short time)。✓ In a short time my hands were covered with pastry.\n✗ the:非特指;✗ an:short 以辅音开头;✗ some:short time 用 a。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',7,NULL,'cloze','{"stem":"第 4 空","context":"After breakfast, I sent ___1___ children to school. Then I decided to make ___2___ meat pies. In ___3___ short time my hands were covered with sticky pastry. At exactly that moment, ___4___ telephone rang.","blank_no":4,"options":["the","a","an","some"],"answer_index":0,"explanation_cn":"特指\"(家里的)那部电话\",用定冠词 the。✓ the telephone rang.\n✗ a / an:此处是特指;✗ some:含义不符。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',8,NULL,'choice','{"stem":"What was the writer making when the phone rang?","options":["A cake","Meat pies","Tea","Bread"],"answer_index":1,"explanation_cn":"课文说 So I decided to make some meat pies,她在做肉馅饼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',8,NULL,'choice','{"stem":"Who was on the telephone?","options":["Her husband","One of her children","The postman","Helen Bates"],"answer_index":3,"explanation_cn":"课文说 I was dismayed when I recognized the voice of Helen Bates,电话是海伦·贝茨打来的。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',8,NULL,'choice','{"stem":"Who rang the doorbell?","options":["The postman, with a registered letter","A neighbor","Helen Bates","Her children"],"answer_index":0,"explanation_cn":"课文说 This time it was the postman and he wanted me to sign for a registered letter。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',9,NULL,'choice','{"stem":"你想说\"我想要一些消息\"(肯定句表''一些''用 some):","options":["I want a information.","I want the some information.","I want some information.","I want any information."],"answer_index":2,"explanation_cn":"肯定句中表示\"一些\"用 some(不用 any);information 不可数,不加 a。✓ I want some information. 场合:肯定地说想要一些东西。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',9,NULL,'choice','{"stem":"你想说\"富人应该帮助穷人\"(the + 形容词表一类人):","options":["The rich should help a poor.","The rich should help the poor.","A rich should help a poor.","Rich should help poor."],"answer_index":1,"explanation_cn":"\"the + 形容词\"表示一类人:the rich(富人)、the poor(穷人)。✓ The rich should help the poor. 场合:泛指某一类人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',9,NULL,'choice','{"stem":"你想说\"我刚回到厨房,门铃就响了\"(刚…就…用 no sooner...than):","options":["I had no sooner got back to the kitchen when the doorbell rang.","I had no sooner got back to the kitchen that the doorbell rang.","I had no sooner got back to the kitchen then the doorbell rang.","I had no sooner got back to the kitchen than the doorbell rang."],"answer_index":3,"explanation_cn":"\"刚一…就…\"用 no sooner … than(与 no sooner 搭配的是 than,不是 then/when/that)。✓ I had no sooner got back to the kitchen than the doorbell rang. 场合:说一件事刚做完另一件就发生。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"annoying 的意思是:","options":["安静的","有趣的","恼人的,讨厌的","方便的"],"answer_index":2,"explanation_cn":"annoying = 恼人的、讨厌的。✓ Nothing could have been more annoying 没什么比这更烦人。\n顺带记:有趣的 = interesting;安静的 = quiet;方便的 = convenient."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"persuade 的意思是:","options":["说服,劝说","命令","拒绝","忘记"],"answer_index":0,"explanation_cn":"persuade = 说服、劝说。✓ persuade her to ring back 说服她再打来。\n顺带记:命令 = order;拒绝 = refuse;忘记 = forget."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"\"I want ___ information about the trip.\"(肯定句,表''一些'')","options":["any","some","a","the"],"answer_index":1,"stem_cn":"我想要一些有关旅行的信息。","explanation_cn":"肯定句中表示\"一些\"用 some;information 不可数不加 a。✓ I want some information about the trip.\n✗ any:多用于疑问、否定句;✗ a:不可数名词不加 a;✗ the:此处非特指。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"\"The rich should help ___ poor.\"(在形容词前加冠词表一类人)","options":["the","a","some","any"],"answer_index":0,"stem_cn":"富人应该帮助穷人。","explanation_cn":"\"the + 形容词\"表示一类人;the poor = 穷人。✓ The rich should help the poor.\n✗ a:表一类人用 the;✗ some/any:此处用 the 表整类。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"\"What a mess!\" 这句话的意思是:","options":["多好啊!","别管它!","真是一团糟!","太安静了!"],"answer_index":2,"explanation_cn":"What a mess! = 真是一团糟、真狼狈(感叹到处乱糟糟)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"\"ring back later\" 这个短语的意思是:","options":["把铃拿回来","挂断电话","响很久","晚点再打电话来"],"answer_index":3,"explanation_cn":"ring back later = 晚点再打电话来、再回电话。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"What two interruptions did the writer have?","options":["The telephone rang, then the doorbell rang","A visitor and a fire","The children came home twice","Two calls from Helen"],"answer_index":0,"passage":"After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home. The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry. At exactly that moment, the telephone rang. Nothing could have been more annoying. I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates. It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess! There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead. This time it was the postman and he wanted me to sign for a registered letter!","explanation_cn":"课文里两次打扰:先是 the telephone rang,后来 the doorbell rang(邮递员)。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"Why was the phone call so annoying?","options":["It was a wrong number","She was asleep","She was in the shower","Her hands were covered in sticky pastry"],"answer_index":3,"passage":"After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home. The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry. At exactly that moment, the telephone rang. Nothing could have been more annoying. I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates. It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess! There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead. This time it was the postman and he wanted me to sign for a registered letter!","explanation_cn":"课文说她正 mixing butter and flour,my hands were soon covered with sticky pastry,此时电话响,所以特别烦人。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"How long did it take to persuade Helen to ring back?","options":["Ten minutes","Five minutes","An hour","One minute"],"answer_index":0,"audio":"After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home. The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry. At exactly that moment, the telephone rang. Nothing could have been more annoying. I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates. It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess! There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead. This time it was the postman and he wanted me to sign for a registered letter!","explanation_cn":"课文说 It took me ten minutes to persuade her to ring back later。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l54',10,NULL,'choice','{"stem":"What did the postman want?","options":["To use her phone","To sell her stamps","Her to sign for a registered letter","To deliver a parcel of pies"],"answer_index":2,"audio":"After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home. The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry. At exactly that moment, the telephone rang. Nothing could have been more annoying. I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates. It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess! There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead. This time it was the postman and he wanted me to sign for a registered letter!","explanation_cn":"课文说 the postman… wanted me to sign for a registered letter。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
